insert into product_categories (slug, name_ko, name_en, description_ko, description_en, business_area_id, sort_order, spec_schema)
values ('water-hydraulics-desalination-pumps', '담수화(해수) 펌프', 'Desalination Pumps', '해수(역삼투 RO 담수화)용 Janus 액시얼 피스톤 펌프. 접수부 전체를 듀플렉스 2205 단조봉재로 제작한 Duplex 빌드와 316L+듀플렉스 조합의 Hybrid 빌드 중 선택할 수 있으며, 에너지 회수 일체형 파워센터도 포함됩니다.', 'Janus axial piston pumps for seawater / reverse-osmosis desalination. Available in full Duplex 2205 bar-stock build or Hybrid 316L + Duplex build, including the Power Centre range with integrated energy recovery.', (select id from business_areas where slug = 'fluid-gas'), 580, '[{"key": "displacement_max", "labelKo": "최대 배제용적", "labelEn": "Max. Displacement", "dataType": "unit_value", "unit": "cc/rev", "required": false, "sortOrder": 1, "showInCardTeaser": true}, {"key": "displacement_min", "labelKo": "최소 배제용적", "labelEn": "Min. Displacement", "dataType": "unit_value", "unit": "cc/rev", "required": false, "sortOrder": 2, "showInCardTeaser": false}, {"key": "max_pressure", "labelKo": "최대 연속 압력", "labelEn": "Max. Cont. Pressure", "dataType": "unit_value", "unit": "bar", "required": false, "sortOrder": 3, "showInCardTeaser": true}, {"key": "max_flow_m3h", "labelKo": "최대 유량", "labelEn": "Max. Water Flow", "dataType": "unit_value", "unit": "m³/hr", "required": false, "sortOrder": 4, "showInCardTeaser": true}, {"key": "max_rpm", "labelKo": "최대 회전수(부스티드)", "labelEn": "Max. RPM (Boosted)", "dataType": "number", "required": false, "sortOrder": 5, "showInCardTeaser": false}, {"key": "max_input_power", "labelKo": "최대 입력 동력", "labelEn": "Max. Input Power", "dataType": "unit_value", "unit": "kW", "required": false, "sortOrder": 6, "showInCardTeaser": false}, {"key": "weight", "labelKo": "중량", "labelEn": "Weight", "dataType": "unit_value", "unit": "kg", "required": false, "sortOrder": 7, "showInCardTeaser": false}, {"key": "build_material", "labelKo": "빌드 재질", "labelEn": "Build Material", "dataType": "select", "options": [{"value": "duplex_2205", "labelKo": "듀플렉스 2205 풀빌드", "labelEn": "Full Duplex 2205"}, {"value": "hybrid_316l_duplex", "labelKo": "하이브리드(316L+듀플렉