insert into product_categories (slug, name_ko, name_en, description_ko, description_en, business_area_id, sort_order, spec_schema)
values ('water-hydraulics-flow-control-valves', '유량 제어 밸브', 'Flow Control Valves', '수돗물용 Janus 유량 제어 밸브. 나선형 포트 설계로 유체 침식에 강하며 수동 조절식과 압력 보상형이 있습니다.', 'Janus flow control valves for tap water. Helical-port design resists flow erosion; available as manual thumb-wheel and pressure-compensated types.', (select id from business_areas where slug = 'fluid-gas'), 610, '[{"key": "control_type", "labelKo": "제어 방식", "labelEn": "Control Type", "dataType": "select", "options": [{"value": "manual", "labelKo": "수동 조절식", "labelEn": "Manual adjustment"}, {"value": "pressure_compensated", "labelKo": "압력 보상형", "labelEn": "Pressure compensated"}], "required": false, "sortOrder": 1, "showInCardTeaser": true}, {"key": "nominal_size", "labelKo": "호칭 크기", "labelEn": "Nominal Size", "dataType": "select", "options": [{"value": "dn3", "labelKo": "DN3", "labelEn": "DN3"}, {"value": "dn6", "labelKo": "DN6", "labelEn": "DN6"}], "required": false, "sortOrder": 2, "showInCardTeaser": true}, {"key": "operating_pressure_range", "labelKo": "사용 압력 범위", "labelEn": "Operating Pressure Range", "dataType": "text", "required": false, "sortOrder": 3, "showInCardTeaser": true}, {"key": "flow_range", "labelKo": "유량 범위", "labelEn": "Flow Range", "dataType": "text", "required": false, "sortOrder": 4, "showInCardTeaser": true}, {"key": "cv_value", "labelKo": "최대 Cv 값", "labelEn": "Max Cv Value", "dataType": "number", "required": false, "sortOrder": 5, "showInCardTeaser": false}, {"key": "adjustment_turns", "labelKo": "조절 회전수 (전개-전폐)", "labelEn": "Adjustment Turns (open-closed)", "dataType": "number", "required": false, "sortOrder": 6, "showInCardTeaser": false}, {"key": "porting", "labelKo": "포트 규격", "labelEn": "Porting", "dataType": "text", "required": false, "sortOrder": 7, "showInCardTeaser": false}, {"key": "body_material", "labelKo": "본체 재질", "labelEn": "Body Material", "dataType": "text", "required": false, "sortOrder": 8, "showInCardTeaser": false}, {"key": "media", "labelKo": "사용 유체", "labelEn": "Media"