insert into product_categories (slug, name_ko, name_en, description_ko, description_en, business_area_id, sort_order, spec_schema)
values ('water-hydraulics-motors', '액시얼 피스톤 모터', 'Axial Piston Motors', '물만을 냉각·윤활제로 사용하는 완전 무급유 Janus 액시얼 피스톤 모터. 316 스테인리스강 표준 구조로 수돗물, 해수, 테크니컬 워터에서 사용 가능하며 ATEX 인증을 획득했습니다.', 'Totally oil-free Janus axial piston motors using water as the only coolant/lubricant. Standard 316 stainless steel construction for tap water, sea water and technical fluids; ATEX approved.', (select id from business_areas where slug = 'fluid-gas'), 620, '[{"key": "displacement_max_cc", "labelKo": "최대 배기량", "labelEn": "Max Displacement", "dataType": "unit_value", "unit": "cc/rev", "required": false, "sortOrder": 1, "showInCardTeaser": true}, {"key": "displacement_min_cc", "labelKo": "최소 배기량", "labelEn": "Min Displacement", "dataType": "unit_value", "unit": "cc/rev", "required": false, "sortOrder": 2, "showInCardTeaser": false}, {"key": "max_speed_rpm", "labelKo": "최대 회전수", "labelEn": "Max Speed", "dataType": "unit_value", "unit": "rpm", "required": false, "sortOrder": 3, "showInCardTeaser": true}, {"key": "min_speed_rpm", "labelKo": "최소 회전수", "labelEn": "Min Speed", "dataType": "unit_value", "unit": "rpm", "required": false, "sortOrder": 4, "showInCardTeaser": false}, {"key": "max_power_kw", "labelKo": "최대 연속 출력", "labelEn": "Max Continuous Power", "dataType": "unit_value", "unit": "kW", "required": false, "sortOrder": 5, "showInCardTeaser": true}, {"key": "max_input_flow_lpm", "labelKo": "최대 입력 유량", "labelEn": "Max Input Flow", "dataType": "unit_value", "unit": "L/min", "required": false, "sortOrder": 6, "showInCardTeaser": false}, {"key": "max_pressure_bar", "labelKo": "최대 연속 압력", "labelEn": "Max Continuous Pressure", "dataType": "unit_value", "unit": "bar", "required": false, "sortOrder": 7, "showInCardTeaser": true}, {"key": "weight_kg", "labelKo": "중량", "labelEn": "Weight", "dataType": "unit_value", "unit": "kg", "required": false, "sortOrder": 8, "showInCardTeaser": false}, {"key": "rotation_options", "labelKo": "회전 방향 옵션", "labelEn": "Rotation Options", "dataType": "text", "required