insert into product_categories (slug, name_ko, name_en, description_ko, description_en, business_area_id, sort_order, spec_schema)
values ('water-hydraulics-power-packs', '워터 유압 파워팩', 'Water Hydraulic Power Packs', 'Janus 펌프-모터 조합에 스테인리스 탱크, 필터, 밸브, 액세서리를 모듈식으로 구성하는 워터 유압 파워 유닛. 소방(워터 미스트)용 파워팩과 이동식 압력 시험 유닛을 포함합니다.', 'Modular water hydraulic power units combining Janus pump-motor assemblies with stainless reservoirs, filters, valves and accessories, including fire-fighting (water mist) power packs and mobile pressure test units.', (select id from business_areas where slug = 'fluid-gas'), 630, '[{"key": "max_pressure", "labelKo": "최대 압력", "labelEn": "Max. Pressure", "dataType": "unit_value", "unit": "bar", "required": false, "sortOrder": 1, "showInCardTeaser": true}, {"key": "flow_range", "labelKo": "유량 범위", "labelEn": "Flow Range", "dataType": "text", "required": false, "sortOrder": 2, "showInCardTeaser": true}, {"key": "motor_power_range", "labelKo": "전동기 동력 범위", "labelEn": "Motor Power Range", "dataType": "text", "required": false, "sortOrder": 3, "showInCardTeaser": false}, {"key": "tank_capacity", "labelKo": "탱크 용량", "labelEn": "Tank Capacity", "dataType": "text", "required": false, "sortOrder": 4, "showInCardTeaser": false}, {"key": "pump_options", "labelKo": "적용 펌프", "labelEn": "Pump Options", "dataType": "text", "required": false, "sortOrder": 5, "showInCardTeaser": false}, {"key": "application", "labelKo": "용도", "labelEn": "Application", "dataType": "select", "options": [{"value": "fire_suppression", "labelKo": "소방(워터 미스트)", "labelEn": "Fire suppression / water mist"}, {"value": "general_power", "labelKo": "범용 동력원", "labelEn": "General power supply"}, {"value": "pressure_testing", "labelKo": "압력 시험", "labelEn": "Pressure testing"}], "required": false, "sortOrder": 6, "showInCardTeaser": true}, {"key": "material", "labelKo": "주요 재질", "labelEn": "Material", "dataType": "text", "required": false, "sortOrder": 7, "showInCardTeaser": false}, {"key": "control_options", "labelKo": "제어 옵션", "labelEn": "Control Options", "dataType": "text", "required": false, "sortOrder": 8, "showInCardTeaser":