insert into product_categories (slug, name_ko, name_en, description_ko, description_en, business_area_id, sort_order, spec_schema)
values ('water-hydraulics-pressure-control-valves', '압력 제어 밸브', 'Pressure Control Valves', '수돗물용 Janus 압력 제어 밸브. 릴리프, 감압, 전자식 비례 압력 제어 타입이 있으며 압력장비지침(PED)에 적합합니다.', 'Janus pressure control valves for tap water: relief, reducing and electronic proportional pressure control types, conforming to the Pressure Equipment Directive.', (select id from business_areas where slug = 'fluid-gas'), 640, '[{"key": "valve_type", "labelKo": "밸브 타입", "labelEn": "Valve Type", "dataType": "select", "options": [{"value": "relief", "labelKo": "릴리프 밸브", "labelEn": "Relief valve"}, {"value": "reducing", "labelKo": "감압 밸브", "labelEn": "Reducing valve"}, {"value": "electronic", "labelKo": "전자식 압력 제어", "labelEn": "Electronic pressure control"}], "required": false, "sortOrder": 1, "showInCardTeaser": true}, {"key": "nominal_size", "labelKo": "호칭 크기", "labelEn": "Nominal Size", "dataType": "select", "options": [{"value": "dn6", "labelKo": "DN6", "labelEn": "DN6"}, {"value": "dn12", "labelKo": "DN12", "labelEn": "DN12"}, {"value": "dn16", "labelKo": "DN16", "labelEn": "DN16"}], "required": false, "sortOrder": 2, "showInCardTeaser": true}, {"key": "max_inlet_pressure_bar", "labelKo": "최대 입구 압력", "labelEn": "Max Inlet Pressure", "dataType": "unit_value", "unit": "bar", "required": false, "sortOrder": 3, "showInCardTeaser": true}, {"key": "setting_range", "labelKo": "설정 압력 범위", "labelEn": "Setting Range", "dataType": "text", "required": false, "sortOrder": 4, "showInCardTeaser": true}, {"key": "max_flow_lpm", "labelKo": "최대 유량", "labelEn": "Max Flow", "dataType": "unit_value", "unit": "L/min", "required": false, "sortOrder": 5, "showInCardTeaser": true}, {"key": "actuation", "labelKo": "구동 방식", "labelEn": "Actuation", "dataType": "select", "options": [{"value": "spring", "labelKo": "스프링(기계식)", "labelEn": "Spring (mechanical)"}, {"value": "stepper_motor", "labelKo": "스테퍼 모터", "labelEn": "Stepper motor"}], "required": false, "sortOrder": 6, "showInCardTeaser": false}, {"key": "porting", "labelKo": "포