insert into product_categories (slug, name_ko, name_en, description_ko, description_en, business_area_id, sort_order, spec_schema)
values ('water-hydraulics-pumps', '워터 유압 펌프', 'Water Hydraulic Pumps', '물을 유일한 윤활·냉각 매체로 사용하는 Janus 액시얼 피스톤 펌프 시리즈. 316 스테인리스 표준 재질, 무급유(오일프리) 구조, ATEX 승인(II 2GD ck T6) 제품군으로 소방·식품·반도체·해양 등 다양한 산업에 적용됩니다.', 'Janus axial piston pumps lubricated and cooled by water only. Standard 316 stainless construction, totally oil-free, ATEX approved (II 2GD ck T6) for fire protection, food, semiconductor, offshore and many other industries.', (select id from business_areas where slug = 'fluid-gas'), 650, '[{"key": "displacement_max", "labelKo": "최대 배제용적", "labelEn": "Max. Displacement", "dataType": "unit_value", "unit": "cc/rev", "required": false, "sortOrder": 1, "showInCardTeaser": true}, {"key": "displacement_min", "labelKo": "최소 배제용적", "labelEn": "Min. Displacement", "dataType": "unit_value", "unit": "cc/rev", "required": false, "sortOrder": 2, "showInCardTeaser": false}, {"key": "max_pressure", "labelKo": "최대 연속 압력", "labelEn": "Max. Cont. Pressure", "dataType": "unit_value", "unit": "bar", "required": false, "sortOrder": 3, "showInCardTeaser": true}, {"key": "max_flow", "labelKo": "최대 유량", "labelEn": "Max. Water Flow", "dataType": "unit_value", "unit": "L/min", "required": false, "sortOrder": 4, "showInCardTeaser": true}, {"key": "max_rpm", "labelKo": "최대 회전수", "labelEn": "Max. RPM", "dataType": "number", "required": false, "sortOrder": 5, "showInCardTeaser": false}, {"key": "max_input_power", "labelKo": "최대 입력 동력", "labelEn": "Max. Input Power", "dataType": "unit_value", "unit": "kW", "required": false, "sortOrder": 6, "showInCardTeaser": false}, {"key": "weight", "labelKo": "중량", "labelEn": "Weight", "dataType": "unit_value", "unit": "kg", "required": false, "sortOrder": 7, "showInCardTeaser": false}, {"key": "pump_type", "labelKo": "펌프 형식", "labelEn": "Pump Type", "dataType": "select", "options": [{"value": "fixed_displacement", "labelKo": "정용량형", "labelEn": "Fixed displacement"}, {"value": "variable_displacement", "labelKo": "가변용량형", "labelEn": "Variable displacement"}, {"value": "fire_pump", "labelKo": "소방(미스트)용", "labelEn": "Fire / water-mist pump"}], "required": false, "sortOrder": 8, "showInCardTeaser": false}, {"key": "inlet_type", "labelKo": "흡입 구성", "labelEn": "Inlet Configuration", "dataType": "select", "options": [{"value": "unboosted_2port", "labelKo": "2포트 비가압(언부스티드)", "labelEn": "2-port unboosted"}, {"value": "boosted_3port", "labelKo": "3포트 가압(부스티드)", "labelEn": "3-port boosted"}, {"value": "both", "labelKo": "2포트/3포트 선택", "labelEn": "Unboosted or boosted"}], "required": false, "sortOrder": 9, "showInCardTeaser": false}, {"key": "material", "labelKo": "주요 재질", "labelEn": "Material", "dataType": "select", "options": [{"value": "stainless_316", "labelKo": "스테인리스 316", "labelEn": "316 stainless steel"}, {"value": "stainless_316l", "labelKo": "스테인리스 316L", "labelEn": "316L stainless steel"}], "required": false, "sortOrder": 10, "showInCardTeaser": false}, {"key": "temp_range", "labelKo": "사용 온도 범위", "labelEn": "Temperature Range", "dataType": "text", "required": false, "sortOrder": 11, "showInCardTeaser": false}, {"key": "atex", "labelKo": "ATEX 승인", "labelEn": "ATEX Approved", "dataType": "boolean", "required": false, "sortOrder": 12, "showInCardTeaser": false}, {"key": "displacement_max_cc", "labelKo": "최대 배기량", "labelEn": "Max Displacement", "dataType": "unit_value", "unit": "cc/rev", "required": false, "sortOrder": 13, "showInCardTeaser": true}, {"key": "displacement_min_cc", "labelKo": "최소 배기량", "labelEn": "Min Displacement", "dataType": "unit_value", "unit": "cc/rev", "required": false, "sortOrder": 14, "showInCardTeaser": false}, {"key": "max_speed_rpm", "labelKo": "최대 회전수 (비부스트)", "labelEn": "Max Speed (unboosted)", "dataType": "unit_value", "unit": "rpm", "required": false, "sortOrder": 15, "showInCardTeaser": false}, {"key": "boosted_speed_rpm", "labelKo": "최대 회전수 (부스트)", "labelEn": "Max Speed (boosted)", "dataType": "unit_value", "unit": "rpm", "required": false, "sortOrder": 16, "showInCardTeaser": false}, {"